-- English names for kon-crm: the public API and the database move to English.
--
-- It renames in place, so data is kept, and every step checks first: it works on a fresh chain,
-- on a database at the previous chain's state, and if a name was already changed by hand.

-- Policies that name something that changes: they come back in the next file.
DROP POLICY IF EXISTS crm_activities_equipo ON crm_activities;
DROP POLICY IF EXISTS crm_companies_equipo ON crm_companies;
DROP POLICY IF EXISTS crm_contacts_equipo ON crm_contacts;
DROP POLICY IF EXISTS crm_deals_equipo ON crm_deals;
DROP POLICY IF EXISTS crm_documents_equipo ON crm_documents;
DROP POLICY IF EXISTS crm_entity_configs_equipo ON crm_entity_configs;
DROP POLICY IF EXISTS crm_pipeline_stages_equipo ON crm_pipeline_stages;
DROP POLICY IF EXISTS crm_pipelines_equipo ON crm_pipelines;
DROP POLICY IF EXISTS crm_stage_transitions_equipo ON crm_stage_transitions;

-- Stored scopes and tool names of this kon: agents, OAuth grants and pending approvals keep working.
-- A denial keeps its "!". Rows without an old name are not touched. Tables that do not exist are skipped.
DO $$
DECLARE
  m jsonb := '{"kon:crm:listar-empresas":"kon:crm:list-companies","crm:listar-empresas":"crm:list-companies","crm__listar-empresas":"crm__list-companies","kon:crm:crear-empresa":"kon:crm:create-company","crm:crear-empresa":"crm:create-company","crm__crear-empresa":"crm__create-company","kon:crm:ver-empresa":"kon:crm:get-company","crm:ver-empresa":"crm:get-company","crm__ver-empresa":"crm__get-company","kon:crm:editar-empresa":"kon:crm:update-company","crm:editar-empresa":"crm:update-company","crm__editar-empresa":"crm__update-company","kon:crm:borrar-empresa":"kon:crm:delete-company","crm:borrar-empresa":"crm:delete-company","crm__borrar-empresa":"crm__delete-company","kon:crm:listar-contactos":"kon:crm:list-contacts","crm:listar-contactos":"crm:list-contacts","crm__listar-contactos":"crm__list-contacts","kon:crm:crear-contacto":"kon:crm:create-contact","crm:crear-contacto":"crm:create-contact","crm__crear-contacto":"crm__create-contact","kon:crm:ver-contacto":"kon:crm:get-contact","crm:ver-contacto":"crm:get-contact","crm__ver-contacto":"crm__get-contact","kon:crm:editar-contacto":"kon:crm:update-contact","crm:editar-contacto":"crm:update-contact","crm__editar-contacto":"crm__update-contact","kon:crm:borrar-contacto":"kon:crm:delete-contact","crm:borrar-contacto":"crm:delete-contact","crm__borrar-contacto":"crm__delete-contact","kon:crm:listar-embudos":"kon:crm:list-pipelines","crm:listar-embudos":"crm:list-pipelines","crm__listar-embudos":"crm__list-pipelines","kon:crm:crear-embudo":"kon:crm:create-pipeline","crm:crear-embudo":"crm:create-pipeline","crm__crear-embudo":"crm__create-pipeline","kon:crm:ver-embudo":"kon:crm:get-pipeline","crm:ver-embudo":"crm:get-pipeline","crm__ver-embudo":"crm__get-pipeline","kon:crm:editar-embudo":"kon:crm:update-pipeline","crm:editar-embudo":"crm:update-pipeline","crm__editar-embudo":"crm__update-pipeline","kon:crm:borrar-embudo":"kon:crm:delete-pipeline","crm:borrar-embudo":"crm:delete-pipeline","crm__borrar-embudo":"crm__delete-pipeline","kon:crm:crear-etapa":"kon:crm:create-stage","crm:crear-etapa":"crm:create-stage","crm__crear-etapa":"crm__create-stage","kon:crm:editar-etapa":"kon:crm:update-stage","crm:editar-etapa":"crm:update-stage","crm__editar-etapa":"crm__update-stage","kon:crm:borrar-etapa":"kon:crm:delete-stage","crm:borrar-etapa":"crm:delete-stage","crm__borrar-etapa":"crm__delete-stage","kon:crm:listar-oportunidades":"kon:crm:list-deals","crm:listar-oportunidades":"crm:list-deals","crm__listar-oportunidades":"crm__list-deals","kon:crm:crear-oportunidad":"kon:crm:create-deal","crm:crear-oportunidad":"crm:create-deal","crm__crear-oportunidad":"crm__create-deal","kon:crm:ver-oportunidad":"kon:crm:get-deal","crm:ver-oportunidad":"crm:get-deal","crm__ver-oportunidad":"crm__get-deal","kon:crm:editar-oportunidad":"kon:crm:update-deal","crm:editar-oportunidad":"crm:update-deal","crm__editar-oportunidad":"crm__update-deal","kon:crm:borrar-oportunidad":"kon:crm:delete-deal","crm:borrar-oportunidad":"crm:delete-deal","crm__borrar-oportunidad":"crm__delete-deal","kon:crm:ver-tablero":"kon:crm:get-board","crm:ver-tablero":"crm:get-board","crm__ver-tablero":"crm__get-board","kon:crm:reordenar-oportunidades":"kon:crm:reorder-deals","crm:reordenar-oportunidades":"crm:reorder-deals","crm__reordenar-oportunidades":"crm__reorder-deals","kon:crm:listar-actividades":"kon:crm:list-activities","crm:listar-actividades":"crm:list-activities","crm__listar-actividades":"crm__list-activities","kon:crm:crear-actividad":"kon:crm:create-activity","crm:crear-actividad":"crm:create-activity","crm__crear-actividad":"crm__create-activity","kon:crm:ver-actividad":"kon:crm:get-activity","crm:ver-actividad":"crm:get-activity","crm__ver-actividad":"crm__get-activity","kon:crm:editar-actividad":"kon:crm:update-activity","crm:editar-actividad":"crm:update-activity","crm__editar-actividad":"crm__update-activity","kon:crm:completar-actividad":"kon:crm:complete-activity","crm:completar-actividad":"crm:complete-activity","crm__completar-actividad":"crm__complete-activity","kon:crm:borrar-actividad":"kon:crm:delete-activity","crm:borrar-actividad":"crm:delete-activity","crm__borrar-actividad":"crm__delete-activity","kon:crm:ver-estadisticas":"kon:crm:get-stats","crm:ver-estadisticas":"crm:get-stats","crm__ver-estadisticas":"crm__get-stats","kon:crm:listar-entidades":"kon:crm:list-entities","crm:listar-entidades":"crm:list-entities","crm__listar-entidades":"crm__list-entities","kon:crm:crear-entidad":"kon:crm:create-entity","crm:crear-entidad":"crm:create-entity","crm__crear-entidad":"crm__create-entity","kon:crm:editar-entidad":"kon:crm:update-entity","crm:editar-entidad":"crm:update-entity","crm__editar-entidad":"crm__update-entity","kon:crm:validar-movimiento":"kon:crm:validate-move","crm:validar-movimiento":"crm:validate-move","crm__validar-movimiento":"crm__validate-move","kon:crm:ver-historial-oportunidad":"kon:crm:get-deal-history","crm:ver-historial-oportunidad":"crm:get-deal-history","crm__ver-historial-oportunidad":"crm__get-deal-history","kon:crm:ver-tiempos-de-ciclo":"kon:crm:get-cycle-times","crm:ver-tiempos-de-ciclo":"crm:get-cycle-times","crm__ver-tiempos-de-ciclo":"crm__get-cycle-times","kon:crm:configurar-etapa":"kon:crm:configure-stage","crm:configurar-etapa":"crm:configure-stage","crm__configurar-etapa":"crm__configure-stage","kon:crm:listar-documentos-oportunidad":"kon:crm:list-deal-documents","crm:listar-documentos-oportunidad":"crm:list-deal-documents","crm__listar-documentos-oportunidad":"crm__list-deal-documents","kon:crm:crear-documento":"kon:crm:create-document","crm:crear-documento":"crm:create-document","crm__crear-documento":"crm__create-document","kon:crm:borrar-documento":"kon:crm:delete-document","crm:borrar-documento":"crm:delete-document","crm__borrar-documento":"crm__delete-document","kon:crm:mover-oportunidad":"kon:crm:move-deal","crm:mover-oportunidad":"crm:move-deal","crm__mover-oportunidad":"crm__move-deal"}'::jsonb;
  ops jsonb := '{"listar-empresas":"list-companies","crear-empresa":"create-company","ver-empresa":"get-company","editar-empresa":"update-company","borrar-empresa":"delete-company","listar-contactos":"list-contacts","crear-contacto":"create-contact","ver-contacto":"get-contact","editar-contacto":"update-contact","borrar-contacto":"delete-contact","listar-embudos":"list-pipelines","crear-embudo":"create-pipeline","ver-embudo":"get-pipeline","editar-embudo":"update-pipeline","borrar-embudo":"delete-pipeline","crear-etapa":"create-stage","editar-etapa":"update-stage","borrar-etapa":"delete-stage","listar-oportunidades":"list-deals","crear-oportunidad":"create-deal","ver-oportunidad":"get-deal","editar-oportunidad":"update-deal","borrar-oportunidad":"delete-deal","ver-tablero":"get-board","reordenar-oportunidades":"reorder-deals","listar-actividades":"list-activities","crear-actividad":"create-activity","ver-actividad":"get-activity","editar-actividad":"update-activity","completar-actividad":"complete-activity","borrar-actividad":"delete-activity","ver-estadisticas":"get-stats","listar-entidades":"list-entities","crear-entidad":"create-entity","editar-entidad":"update-entity","validar-movimiento":"validate-move","ver-historial-oportunidad":"get-deal-history","ver-tiempos-de-ciclo":"get-cycle-times","configurar-etapa":"configure-stage","listar-documentos-oportunidad":"list-deal-documents","crear-documento":"create-document","borrar-documento":"delete-document","mover-oportunidad":"move-deal"}'::jsonb;
  t record;
BEGIN
  FOR t IN SELECT * FROM (VALUES
    ('agent_identities', 'scopes'), ('agent_identities', 'allowed_tools'), ('agent_proposals', 'scopes'),
    ('oauth_authorization_requests', 'requested_scopes'), ('oauth_codes', 'scopes'), ('oauth_grants', 'scopes'), ('oauth_tokens', 'scopes')
  ) AS v(tbl, col) LOOP
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t.tbl AND column_name = t.col) THEN
      EXECUTE format($f$
        UPDATE %1$I SET %2$I = (
          SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(e) <> 'string' THEN e
                                         WHEN left(e #>> '{}', 1) = '!' THEN to_jsonb('!' || coalesce($1 ->> substr(e #>> '{}', 2), substr(e #>> '{}', 2)))
                                         ELSE to_jsonb(coalesce($1 ->> (e #>> '{}'), e #>> '{}')) END), '[]'::jsonb)
          FROM jsonb_array_elements(%2$I) AS e)
        WHERE jsonb_typeof(%2$I) = 'array' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(%2$I) AS e
          WHERE jsonb_typeof(e) = 'string' AND $1 ? ltrim(e #>> '{}', '!'))
      $f$, t.tbl, t.col) USING m;
    END IF;
  END LOOP;
  IF to_regclass('public.agent_proposals') IS NOT NULL THEN
    UPDATE agent_proposals SET
        operation_key = coalesce(m ->> operation_key, operation_key),
        tool = coalesce(m ->> tool, tool),
        operation_id = coalesce(ops ->> operation_id, operation_id)
      WHERE status = 'pending' AND (m ? coalesce(operation_key, '') OR m ? coalesce(tool, ''));
  END IF;
END $$;
